(window.QBANK = window.QBANK || []).push(
  {"id": "prac-sc-1", "exam": "JEE", "subject": "Physics", "chapter": "Units & Measurements", "type": "mcq", "difficulty": 2, "q": "The van der Waals equation is $\\left(P+\\frac{a}{V^2}\\right)(V-b)=RT$, where P is pressure, V is molar volume and T is temperature. The dimensional formula of b is the same as that of:", "options": ["P", "V", "PV²", "RT"], "answer": 1, "hint": "Only like quantities can be subtracted.", "solution": "$V-b$ ⇒ b has the dimensions of V.", "source": "Sri Chaitanya · Total Physics Important Questions · Q1", "kind": "practice"},
  {"id": "prac-sc-2", "exam": "JEE", "subject": "Physics", "chapter": "Units & Measurements", "type": "mcq", "difficulty": 2, "q": "The van der Waals equation is $\\left(P+\\frac{a}{V^2}\\right)(V-b)=RT$, where P is pressure, V is molar volume and T is temperature. The dimensional formula of a is the same as that of:", "options": ["V²", "P", "PV²", "RT"], "answer": 2, "hint": "$a/V^2$ adds to P.", "solution": "$[a]=[P][V^2]$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q2", "kind": "practice"},
  {"id": "prac-sc-3", "exam": "JEE", "subject": "Physics", "chapter": "Units & Measurements", "type": "mcq", "difficulty": 2, "q": "The van der Waals equation is $\\left(P+\\frac{a}{V^2}\\right)(V-b)=RT$, where P is pressure, V is molar volume and T is temperature. Which does NOT have the same dimensions as RT?", "options": ["PV", "Pb", "a/V²", "ab/V²"], "answer": 2, "hint": "RT has dimensions of PV (energy per mole).", "solution": "$a/V^2$ has dimensions of P only. $Pb$ and $ab/V^2=PV^2\\cdot V/V^2$ both equal PV.", "source": "Sri Chaitanya · Total Physics Important Questions · Q3", "kind": "practice"},
  {"id": "prac-sc-5", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 2, "q": "Two vectors vary with time as $\\vec a=3t\\hat i+4t^2\\hat j$ and $\\vec b=(6t+3)\\hat i+(7\\sin t)\\hat j$. The rate of change of $\\vec a\\cdot\\vec b$ at t = 0 is:", "options": ["36", "9", "28", "45"], "answer": 1, "hint": "Differentiate $3t(6t+3)+28t^2\\sin t$.", "solution": "$\\frac{d}{dt}=36t+9+(\\ldots)t$ terms ⇒ 9 at t = 0.", "source": "Sri Chaitanya · Total Physics Important Questions · Q5", "kind": "practice"},
  {"id": "prac-sc-6", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 1, "q": "Two vectors vary with time as $\\vec a=3t\\hat i+4t^2\\hat j$ and $\\vec b=(6t+3)\\hat i+(7\\sin t)\\hat j$. The rate of change of $\\vec a\\cdot(\\vec a\\times\\vec b)$ at t = 0 is:", "options": ["72", "36", "48", "zero"], "answer": 3, "hint": "$\\vec a\\times\\vec b$ is perpendicular to $\\vec a$.", "solution": "$\\vec a\\cdot(\\vec a\\times\\vec b)=0$ at all times, so its rate is zero.", "source": "Sri Chaitanya · Total Physics Important Questions · Q6", "kind": "practice"},
  {"id": "prac-sc-7", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A 2 kg particle starts from x = 0 at t = 0 under a force $F=(10+4x)$ N along the x-axis on a frictionless track, and moves 5 m. Its speed after 5 m (m/s) is:", "options": ["5", "10", "20", "30"], "answer": 1, "hint": "Work = $\\int F\\,dx$ = change in KE.", "solution": "$W=\\int_0^5(10+4x)dx=100$ J $=\\frac12(2)v^2$ ⇒ v = 10 m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q7", "kind": "practice"},
  {"id": "prac-sc-8", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 1, "q": "A 2 kg particle starts from x = 0 at t = 0 under a force $F=(10+4x)$ N along the x-axis on a frictionless track, and moves 5 m. The force at that moment (N) is:", "options": ["20", "5", "30", "40"], "answer": 2, "hint": "Put x = 5.", "solution": "$F=10+20=30$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q8", "kind": "practice"},
  {"id": "prac-sc-9", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A 2 kg particle starts from x = 0 at t = 0 under a force $F=(10+4x)$ N along the x-axis on a frictionless track, and moves 5 m. The instantaneous power at that moment is:", "options": ["200 W", "300 W", "400 W", "500 W"], "answer": 1, "hint": "P = Fv.", "solution": "$30\\times10=300$ W.", "source": "Sri Chaitanya · Total Physics Important Questions · Q9", "kind": "practice"},
  {"id": "prac-sc-10", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 3, "q": "A solid body rotates about a fixed axis as $\\theta=kt-bt^3$, with k = 6.0 rad/s and b = 2.0 rad/s³. The mean angular velocity from t = 0 until the body stops is:", "options": ["2 rad/s", "4 rad/s", "3 rad/s", "12 rad/s"], "answer": 1, "hint": "It stops when $\\omega=k-3bt^2=0$.", "solution": "t = 1 s; $\\langle\\omega\\rangle=\\frac{\\theta(1)}{1}=6-2=4$ rad/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q10", "kind": "practice"},
  {"id": "prac-sc-11", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 3, "q": "A solid body rotates about a fixed axis as $\\theta=kt-bt^3$, with k = 6.0 rad/s and b = 2.0 rad/s³. The magnitude of the mean angular acceleration from t = 0 until the body stops is:", "options": ["6 rad/s²", "24 rad/s²", "18 rad/s²", "12 rad/s²"], "answer": 0, "hint": "$\\langle\\alpha\\rangle=\\Delta\\omega/\\Delta t$.", "solution": "ω goes from 6 to 0 in 1 s ⇒ 6 rad/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q11", "kind": "practice"},
  {"id": "prac-sc-12", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 2, "q": "A solid body rotates about a fixed axis as $\\theta=kt-bt^3$, with k = 6.0 rad/s and b = 2.0 rad/s³. The magnitude of the angular acceleration at the moment the body stops is:", "options": ["18 rad/s²", "24 rad/s²", "6 rad/s²", "12 rad/s²"], "answer": 3, "hint": "$\\alpha=-6bt$.", "solution": "At t = 1 s: |α| = 12 rad/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q12", "kind": "practice"},
  {"id": "prac-sc-13", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 2, "q": "A boat of mass M sails with velocity $v_0\\hat i$. At t = 0 its engine stops; water exerts a drag force $\\vec F=-kv\\hat i$, so $\\vec v=(Ce^{-kt/M})\\hat i$. At the same moment a light ball is thrown vertically up from the boat. The constant C is:", "options": ["$v_0/2$", "$v_0$", "$v_0\\frac{M}{m}$", "$v_0\\frac{m}{M}$"], "answer": 1, "hint": "Put t = 0.", "solution": "$v(0)=C=v_0$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q13", "kind": "practice"},
  {"id": "prac-sc-14", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A boat of mass M sails with velocity $v_0\\hat i$. At t = 0 its engine stops; water exerts a drag force $\\vec F=-kv\\hat i$, so $\\vec v=(Ce^{-kt/M})\\hat i$. At the same moment a light ball is thrown vertically up from the boat. The acceleration of the boat as a function of time is:", "options": ["$\\frac{kv_0}{M}e^{-kt/M}\\hat i$", "$\\frac{kv_0}{M}e^{-kt/M}(-\\hat i)^{-1}$", "$-\\frac{kv_0}{M}e^{-kt/M}\\hat i$", "$-\\frac{kv_0}{M}e^{kt/M}\\hat i$"], "answer": 2, "hint": "Differentiate $v_0e^{-kt/M}$.", "solution": "$a=-\\frac{kv_0}{M}e^{-kt/M}\\hat i$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q14", "kind": "practice"},
  {"id": "prac-sc-15", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 4, "q": "A boat of mass M sails with velocity $v_0\\hat i$. At t = 0 its engine stops; water exerts a drag force $\\vec F=-kv\\hat i$, so $\\vec v=(Ce^{-kt/M})\\hat i$. At the same moment a light ball is thrown vertically up from the boat. The horizontal acceleration of the ball in the ground frame ($a_x$) and in the boat frame ($a_{x'}$) are respectively:", "options": ["$0$; $\\frac{kv_0}{M}e^{-kt/M}$", "$0$; $-\\frac{kv_0}{M}e^{-kt/M}$", "$a_x=a_{x'}=-\\frac{kv_0}{M}e^{-kt/M}$", "$0$; $-\\frac{kv_0}{M}e^{kt/M}$"], "answer": 0, "hint": "No horizontal force on the ball; the boat decelerates.", "solution": "Ground: $a_x=0$. Boat frame: $a_{x'}=0-a_{boat}=+\\frac{kv_0}{M}e^{-kt/M}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q15", "kind": "practice"},
  {"id": "prac-sc-16", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 1, "q": "A particle starts from rest with constant acceleration 4 m/s² for 4 s, then retards uniformly for the next 8 s and comes to rest. The average acceleration over the whole motion is:", "options": ["4 m/s²", "zero", "8 m/s²", "−4 m/s²"], "answer": 1, "hint": "Compare initial and final velocity.", "solution": "It starts and ends at rest ⇒ zero.", "source": "Sri Chaitanya · Total Physics Important Questions · Q16", "kind": "practice"},
  {"id": "prac-sc-17", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 2, "q": "A particle starts from rest with constant acceleration 4 m/s² for 4 s, then retards uniformly for the next 8 s and comes to rest. The average speed over the whole motion is:", "options": ["8 m/s", "zero", "4 m/s", "16 m/s"], "answer": 0, "hint": "Max speed 16 m/s; add the two areas under v–t.", "solution": "Distance $=32+64=96$ m in 12 s ⇒ 8 m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q17", "kind": "practice"},
  {"id": "prac-sc-18", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 2, "q": "A particle starts from rest with constant acceleration 4 m/s² for 4 s, then retards uniformly for the next 8 s and comes to rest. The average velocity over the whole motion is:", "options": ["zero", "8 m/s", "2 m/s", "4 m/s"], "answer": 1, "hint": "The motion is in one direction.", "solution": "$96/12=8$ m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q18", "kind": "practice"},
  {"id": "prac-sc-19", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 2, "q": "The radius vector of a point relative to the origin varies as $\\vec r=at\\hat i-bt^2\\hat j$, where a and b are positive constants. The equation of the trajectory is:", "options": ["$y=x^2\\frac{b}{a^2}$", "$y=-x\\frac{b}{a^2}$", "$y=-x^2\\frac{b}{a^2}$", "$y=-x^2\\frac{b}{a}$"], "answer": 2, "hint": "Eliminate t using $x=at$.", "solution": "$y=-b\\left(\\frac xa\\right)^2$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q19", "kind": "practice"},
  {"id": "prac-sc-20", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 1, "q": "The radius vector of a point relative to the origin varies as $\\vec r=at\\hat i-bt^2\\hat j$, where a and b are positive constants. The velocity as a function of time is:", "options": ["$-a\\hat i-2bt\\hat j$", "$a\\hat i-2b\\hat j$", "$a\\hat i-2bt\\hat j$", "$a\\hat i+2bt\\hat j$"], "answer": 2, "hint": "Differentiate $\\vec r$.", "solution": "$\\vec v=a\\hat i-2bt\\hat j$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q20", "kind": "practice"},
  {"id": "prac-sc-21", "exam": "JEE", "subject": "Physics", "chapter": "Kinematics", "type": "mcq", "difficulty": 1, "q": "The radius vector of a point relative to the origin varies as $\\vec r=at\\hat i-bt^2\\hat j$, where a and b are positive constants. The acceleration of the point is:", "options": ["$2a\\hat j$", "$2b^2\\hat j$", "$2b\\hat j$", "$-2b\\hat j$"], "answer": 3, "hint": "Differentiate $\\vec v$.", "solution": "$\\vec a=-2b\\hat j$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q21", "kind": "practice"},
  {"id": "prac-sc-22", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A 5 kg block is pulled vertically up by a 200 N force. Hanging from it is a uniform 3 kg rope (A at its top, B at its midpoint, C at its bottom) with a 2 kg block tied at C. (g = 10 m/s²) The tension at A is:", "options": ["100 N", "150 N", "200 N", "50 N"], "answer": 0, "hint": "Whole system (10 kg) accelerates at $a=\\frac{200-100}{10}$.", "solution": "$a=10$ m/s². $T_A=(3+2)(g+a)=100$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q22", "kind": "practice"},
  {"id": "prac-sc-23", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A 5 kg block is pulled vertically up by a 200 N force. Hanging from it is a uniform 3 kg rope (A at its top, B at its midpoint, C at its bottom) with a 2 kg block tied at C. (g = 10 m/s²) The tension at B is:", "options": ["60 N", "40 N", "70 N", "100 N"], "answer": 2, "hint": "Below B hang 1.5 kg of rope + 2 kg.", "solution": "$T_B=3.5\\times20=70$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q23", "kind": "practice"},
  {"id": "prac-sc-24", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 2, "q": "A 5 kg block is pulled vertically up by a 200 N force. Hanging from it is a uniform 3 kg rope (A at its top, B at its midpoint, C at its bottom) with a 2 kg block tied at C. (g = 10 m/s²) The tension at C is:", "options": ["10 N", "30 N", "20 N", "40 N"], "answer": 3, "hint": "Only the 2 kg block hangs below C.", "solution": "$T_C=2\\times20=40$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q24", "kind": "practice"},
  {"id": "prac-sc-25", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A light string over a fixed massless pulley carries a 10 kg block on one side and a massless pan on the other; the pan holds a 3 kg block with a 2 kg block resting on top of it. The force exerted by the 3 kg block on the 2 kg block is:", "options": ["8g/3 N", "5g/3 N", "20g/3 N", "10g/3 N"], "answer": 0, "hint": "$a=\\frac{(10-5)g}{15}=\\frac g3$; the pan side moves up.", "solution": "$N=2\\left(g+\\frac g3\\right)=\\frac{8g}{3}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q25", "kind": "practice"},
  {"id": "prac-sc-26", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A light string over a fixed massless pulley carries a 10 kg block on one side and a massless pan on the other; the pan holds a 3 kg block with a 2 kg block resting on top of it. The force exerted by the 3 kg block on the pan is:", "options": ["8g/3 N", "5g/3 N", "20g/3 N", "10g/3 N"], "answer": 2, "hint": "The pan must accelerate both blocks (5 kg) upward.", "solution": "$5\\left(g+\\frac g3\\right)=\\frac{20g}{3}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q26", "kind": "practice"},
  {"id": "prac-sc-27", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A light string over a fixed massless pulley carries a 10 kg block on one side and a massless pan on the other; the pan holds a 3 kg block with a 2 kg block resting on top of it. The tension in the string is:", "options": ["8g/3 N", "5g/3 N", "20g/3 N", "10g/3 N"], "answer": 2, "hint": "The pan is massless.", "solution": "$T$ = force needed on the 5 kg load $=\\frac{20g}{3}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q27", "kind": "practice"},
  {"id": "prac-sc-28", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 1, "q": "A student pushes a 100 kg crate horizontally, slowly increasing the push: it starts moving only at 400 N. Next, the student applies constant pushes for 1.0 s from rest: 500 N moves it 1.5 m, 600 N moves it 2 m, 700 N moves it 2.5 m (distances within the 1.0 s). (g = 10 m/s²) The coefficient of static friction is approximately:", "options": ["0.25", "2.5", "0.40", "4.0"], "answer": 2, "hint": "Limiting friction = 400 N.", "solution": "$\\mu_s=\\frac{400}{1000}=0.40$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q28", "kind": "practice"},
  {"id": "prac-sc-29", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 1, "q": "A student pushes a 100 kg crate horizontally, slowly increasing the push: it starts moving only at 400 N. Next, the student applies constant pushes for 1.0 s from rest: 500 N moves it 1.5 m, 600 N moves it 2 m, 700 N moves it 2.5 m (distances within the 1.0 s). (g = 10 m/s²) When the push was 50 N the crate did not move, because:", "options": ["the push was weaker than the friction on the crate", "the push equalled the gravitational force", "the push had the same strength as the friction on the crate", "the push was stronger than the friction"], "answer": 2, "hint": "Static friction adjusts itself.", "solution": "At rest, static friction exactly balances the push: 50 N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q29", "kind": "practice"},
  {"id": "prac-sc-30", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 2, "q": "A student pushes a 100 kg crate horizontally, slowly increasing the push: it starts moving only at 400 N. Next, the student applies constant pushes for 1.0 s from rest: 500 N moves it 1.5 m, 600 N moves it 2 m, 700 N moves it 2.5 m (distances within the 1.0 s). (g = 10 m/s²) The coefficient of kinetic friction is approximately:", "options": ["0.30", "0.20", "0.40", "0.50"], "answer": 1, "hint": "From 500 N: $s=\\frac12at^2$ ⇒ a.", "solution": "$a=3$ m/s² ⇒ $500-f=300$ ⇒ $f=200$ N ⇒ $\\mu_k=0.20$ (600 N gives the same).", "source": "Sri Chaitanya · Total Physics Important Questions · Q30", "kind": "practice"},
  {"id": "prac-sc-31", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "Block m on a horizontal table is tied by a light string, over a pulley at the table's edge, to block M on an incline of angle θ. The friction coefficient at both contacts is μ. The maximum value of M/m for which the system stays at rest is:", "options": ["$\\frac{\\mu}{\\cos\\theta+\\mu\\sin\\theta}$", "$\\frac{\\mu}{\\cos\\theta-\\mu\\sin\\theta}$", "$\\frac{\\mu}{\\sin\\theta+\\mu\\cos\\theta}$", "$\\frac{\\mu}{\\sin\\theta-\\mu\\cos\\theta}$"], "answer": 3, "hint": "At the limit, M's weight component = both frictions.", "solution": "$Mg\\sin\\theta=\\mu Mg\\cos\\theta+\\mu mg$ ⇒ $\\frac Mm=\\frac{\\mu}{\\sin\\theta-\\mu\\cos\\theta}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q31", "kind": "practice"},
  {"id": "prac-sc-32", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 2, "q": "Block m on a horizontal table is tied by a light string, over a pulley at the table's edge, to block M on an incline of angle θ. The friction coefficient at both contacts is μ. When $\\tan\\theta<\\mu$:", "options": ["the system will not slide for any value of M/m", "M will move upwards", "M will lose contact with the incline", "both bodies move with constant velocity"], "answer": 0, "hint": "Even without m, would M slide?", "solution": "$\\sin\\theta<\\mu\\cos\\theta$ ⇒ friction alone can hold M, so it never slides.", "source": "Sri Chaitanya · Total Physics Important Questions · Q32", "kind": "practice"},
  {"id": "prac-sc-33", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "Block m on a horizontal table is tied by a light string, over a pulley at the table's edge, to block M on an incline of angle θ. The friction coefficient at both contacts is μ. If M is large enough for the system to slide, the acceleration of M is:", "options": ["$\\frac{Mg\\sin\\theta+\\mu g(m+M\\cos\\theta)}{m+M}$", "$\\frac{Mg\\cos\\theta+\\mu g(m+M\\sin\\theta)}{m+M}$", "$\\frac{Mg\\sin\\theta-\\mu g(m+M\\cos\\theta)}{m+M}$", "$\\frac{Mg\\cos\\theta-\\mu g(m+M\\sin\\theta)}{m+M}$"], "answer": 2, "hint": "Net driving force / total mass.", "solution": "$a=\\frac{Mg\\sin\\theta-\\mu Mg\\cos\\theta-\\mu mg}{m+M}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q33", "kind": "practice"},
  {"id": "prac-sc-34", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A 2 kg block rests on a 4 kg block on a smooth horizontal surface. The friction coefficient between the blocks is 0.20 (g = 10 m/s²). A 12 N horizontal force is applied to the upper block. Its acceleration is:", "options": ["2 m/s²", "1 m/s²", "4 m/s²", "5 m/s²"], "answer": 2, "hint": "Check whether they move together (max friction = 4 N).", "solution": "Together would need 8 N on the lower block > 4 N ⇒ slip. $a_{up}=\\frac{12-4}{2}=4$ m/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q34", "kind": "practice"},
  {"id": "prac-sc-35", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A 2 kg block rests on a 4 kg block on a smooth horizontal surface. The friction coefficient between the blocks is 0.20 (g = 10 m/s²). A 12 N horizontal force is applied to the upper block. The acceleration of the lower block is:", "options": ["2 m/s²", "1 m/s²", "4 m/s²", "5 m/s²"], "answer": 1, "hint": "Only kinetic friction (4 N) drives it.", "solution": "$\\frac44=1$ m/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q35", "kind": "practice"},
  {"id": "prac-sc-36", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "A 2 kg block rests on a 4 kg block on a smooth horizontal surface. The friction coefficient between the blocks is 0.20 (g = 10 m/s²). A 12 N horizontal force is applied to the lower block. The acceleration of the upper block is:", "options": ["2 m/s²", "1 m/s²", "4 m/s²", "5 m/s²"], "answer": 0, "hint": "Together: $a=12/6$; is friction enough?", "solution": "$a=2$ needs 4 N on the upper block = the maximum, so they just move together at 2 m/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q36", "kind": "practice"},
  {"id": "prac-sc-37", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "Three smooth pulleys are connected by a light string as shown; mass m hangs from pulley P₃. The strings are vertical. If all the pulleys are massless, the tension in the string over the pulleys is:", "img": "figures/prac-sc-p13.png", "imgAlt": "Pulley P₁ hangs in a string loop from the ceiling; the string passes over fixed P₂ and under P₃, which carries mass m", "options": ["mg", "zero", "2mg", "mg/2"], "answer": 1, "hint": "Look at the free massless pulley P₁: what balances it?", "solution": "P₁ is massless and hangs only on the string, so the net force on it must vanish ⇒ 2T = 0 ⇒ T = 0 (m falls freely).", "source": "Sri Chaitanya · Total Physics Important Questions · Q37", "kind": "practice"},
  {"id": "prac-sc-39", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 3, "q": "Three smooth pulleys are connected by a light string as shown; mass m hangs from pulley P₃. The strings are vertical. The tension in the string over the pulleys will be non-zero when:", "options": ["mass of P₁ is zero", "mass of P₂ is zero", "mass of P₂ is non-zero", "mass of P₁ is non-zero"], "answer": 3, "hint": "Which pulley's weight must the string support?", "solution": "Only a massive P₁ needs the string to hold it up; P₂ is fixed.", "source": "Sri Chaitanya · Total Physics Important Questions · Q39", "kind": "practice"},
  {"id": "prac-sc-40", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 1, "q": "A 50 g pendulum bob hangs from the ceiling of an elevator (g = 10 m/s²). The tension when the elevator goes up with acceleration 1.2 m/s² is:", "options": ["0.60 N", "0.56 N", "0.75 N", "0.45 N"], "answer": 1, "hint": "$T=m(g+a)$.", "solution": "$0.05\\times11.2=0.56$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q40", "kind": "practice"},
  {"id": "prac-sc-41", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 1, "q": "A 50 g pendulum bob hangs from the ceiling of an elevator (g = 10 m/s²). The tension when the elevator goes up at uniform velocity is:", "options": ["0.5 N", "0.43 N", "0.52 N", "0.75 N"], "answer": 0, "hint": "No acceleration.", "solution": "$T=mg=0.5$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q41", "kind": "practice"},
  {"id": "prac-sc-42", "exam": "JEE", "subject": "Physics", "chapter": "Laws of Motion", "type": "mcq", "difficulty": 2, "q": "A 50 g pendulum bob hangs from the ceiling of an elevator (g = 10 m/s²). The tension when the elevator goes down with deceleration 1.2 m/s² is:", "options": ["0.49 N", "0.43 N", "0.56 N", "0.75 N"], "answer": 2, "hint": "Moving down and slowing ⇒ acceleration is upward.", "solution": "$T=m(g+a)=0.56$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q42", "kind": "practice"},
  {"id": "prac-sc-43", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "Masses m₁ = 2 kg and m₂ = 8 kg hang from the two ends of a string over a fixed pulley. Each rests on a vertical spring fixed to the floor below it: k₁ = 50 N/m under m₁ and k₂ = 70 N/m under m₂. Both springs have the same natural length, the system is in equilibrium and the spring under m₂ is compressed by 0.5 m (g = 10 m/s²). The compression of the first spring (k₁) is:", "options": ["1.3 m", "−0.5 m", "0.5 m", "0.9 m"], "answer": 1, "hint": "Find T from m₂: $T=80-35$.", "solution": "$T=45$ N. For m₁: $45=20+F_1$ ⇒ spring pulls m₁ down with 25 N ⇒ extension 0.5 m, i.e. compression −0.5 m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q43", "kind": "practice"},
  {"id": "prac-sc-44", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "Masses m₁ = 2 kg and m₂ = 8 kg hang from the two ends of a string over a fixed pulley. Each rests on a vertical spring fixed to the floor below it: k₁ = 50 N/m under m₁ and k₂ = 70 N/m under m₂. Both springs have the same natural length, the system is in equilibrium and the spring under m₂ is compressed by 0.5 m (g = 10 m/s²). The acceleration of m₁ just after spring k₁ is cut is:", "options": ["zero", "2.5 m/s²", "3 m/s²", "none"], "answer": 1, "hint": "The string system now: $m_2g-F_2-m_1g$ over 10 kg.", "solution": "$a=\\frac{80-35-20}{10}=2.5$ m/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q44", "kind": "practice"},
  {"id": "prac-sc-45", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "Masses m₁ = 2 kg and m₂ = 8 kg hang from the two ends of a string over a fixed pulley. Each rests on a vertical spring fixed to the floor below it: k₁ = 50 N/m under m₁ and k₂ = 70 N/m under m₂. Both springs have the same natural length, the system is in equilibrium and the spring under m₂ is compressed by 0.5 m (g = 10 m/s²). The acceleration of m₁ just after the string is cut is:", "options": ["20 m/s²", "22.5 m/s²", "25 m/s²", "25.5 m/s²"], "answer": 1, "hint": "Remaining forces on m₁: weight and the stretched spring, both downward.", "solution": "$\\frac{20+25}{2}=22.5$ m/s².", "source": "Sri Chaitanya · Total Physics Important Questions · Q45", "kind": "practice"},
  {"id": "prac-sc-46", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "A smooth track has an inclined straight part of length ℓ (angle θ) that joins smoothly with a circular part of radius R, as shown. A particle is projected up the incline from its bottom. The minimum projection speed $v_0$ for the particle to reach the top of the track is:", "img": "figures/prac-sc-p16.png", "imgAlt": "An incline of length ℓ at angle θ joins a circle of radius R at its upper end", "options": ["$\\sqrt{2g(\\ell\\sin\\theta+R\\cos\\theta)}$", "$\\sqrt{2gR(1-\\cos\\theta)}$", "$\\sqrt{2g\\ell\\sin\\theta}$", "$\\sqrt{2g[R(1-\\cos\\theta)+\\ell\\sin\\theta]}$"], "answer": 3, "hint": "Total rise = incline + circular part above the joint.", "solution": "Height $=\\ell\\sin\\theta+R(1-\\cos\\theta)$ ⇒ $v_0=\\sqrt{2gh}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q46", "kind": "practice"},
  {"id": "prac-sc-48", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 4, "q": "A smooth track has an inclined straight part of length ℓ (angle θ) that joins smoothly with a circular part of radius R, as shown. A particle is projected up the incline from its bottom. If the particle reaches the top of the circular part with a very small speed, it leaves the track when the radius through it makes an angle with the vertical of:", "img": "figures/prac-sc-p16.png", "imgAlt": "An incline of length ℓ at angle θ joins a circle of radius R at its upper end", "options": ["$\\cos^{-1}\\frac13$", "$\\cos^{-1}\\frac23$", "$\\cos^{-1}\\frac35$", "$\\cos^{-1}\\frac45$"], "answer": 1, "hint": "On a convex surface: $mg\\cos\\phi=\\frac{mv^2}{R}$ with $v^2=2gR(1-\\cos\\phi)$.", "solution": "$\\cos\\phi=2(1-\\cos\\phi)$ ⇒ $\\cos\\phi=\\frac23$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q48", "kind": "practice"},
  {"id": "prac-sc-49", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 1, "q": "A slide is 10 m long and 8.0 m high. A boy weighing 200 N climbs the vertical ladder to the top and slides down; average friction on the slide is three-tenths of his weight. The work done by the ladder on the boy as he climbs is:", "options": ["600 J", "1600 J", "zero", "800 J"], "answer": 2, "hint": "Does the point where the force acts move?", "solution": "The ladder's force acts at a stationary contact point ⇒ zero work.", "source": "Sri Chaitanya · Total Physics Important Questions · Q49", "kind": "practice"},
  {"id": "prac-sc-50", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A slide is 10 m long and 8.0 m high. A boy weighing 200 N climbs the vertical ladder to the top and slides down; average friction on the slide is three-tenths of his weight. The work done by the slide on the boy as he comes down is:", "options": ["1600 J", "−600 J", "zero", "500 J"], "answer": 1, "hint": "Normal force does no work; friction acts over 10 m.", "solution": "$-0.3\\times200\\times10=-600$ J.", "source": "Sri Chaitanya · Total Physics Important Questions · Q50", "kind": "practice"},
  {"id": "prac-sc-51", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A slide is 10 m long and 8.0 m high. A boy weighing 200 N climbs the vertical ladder to the top and slides down; average friction on the slide is three-tenths of his weight. The work done by the forces inside the boy's body (while climbing) is:", "options": ["zero", "−600 J", "800 J", "1600 J"], "answer": 3, "hint": "His muscles supply the potential energy gained.", "solution": "$mgh=200\\times8=1600$ J.", "source": "Sri Chaitanya · Total Physics Important Questions · Q51", "kind": "practice"},
  {"id": "prac-sc-53", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "A 2 kg particle on a string moves in a vertical circle of radius 2 m. (g = 10 m/s²) It is given 12 m/s at the lowest point. The tension at the highest point is:", "options": ["100 N", "44 N", "144 N", "264 N"], "answer": 1, "hint": "$v_{top}^2=u^2-4gR$.", "solution": "$v^2=144-80=64$ ⇒ $T=\\frac{2\\times64}{2}-20=44$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q53", "kind": "practice"},
  {"id": "prac-sc-54", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A 2 kg particle on a string moves in a vertical circle of radius 2 m. (g = 10 m/s²) It is given 10 m/s at the lowest point. Its speed when the string makes 60° with the downward vertical is:", "options": ["$2\\sqrt5$ m/s", "$4\\sqrt5$ m/s", "$5\\sqrt2$ m/s", "5 m/s"], "answer": 1, "hint": "Rise $h=R(1-\\cos60°)=1$ m.", "solution": "$v^2=100-20=80$ ⇒ $4\\sqrt5$ m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q54", "kind": "practice"},
  {"id": "prac-sc-55", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 1, "q": "A ball of mass m on a string of length l moves in a vertical circle; its speed at the lowest point is $\\sqrt{20gl}$. Only tension and gravity act. The motion of the ball is:", "options": ["circular motion with variable speed", "circular motion with constant speed", "circular motion with constant angular acceleration", "none of these"], "answer": 0, "hint": "Gravity has a tangential component.", "solution": "Speed changes with height; the tangential acceleration $g\\sin\\theta$ also varies.", "source": "Sri Chaitanya · Total Physics Important Questions · Q55", "kind": "practice"},
  {"id": "prac-sc-56", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 1, "q": "A ball of mass m on a string of length l moves in a vertical circle; its speed at the lowest point is $\\sqrt{20gl}$. Only tension and gravity act. At the highest point, the tangential acceleration is:", "options": ["g", "0", "5g", "16g"], "answer": 1, "hint": "At the top, gravity is radial.", "solution": "Gravity points to the centre ⇒ tangential acceleration 0.", "source": "Sri Chaitanya · Total Physics Important Questions · Q56", "kind": "practice"},
  {"id": "prac-sc-57", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "A ball of mass m on a string of length l moves in a vertical circle; its speed at the lowest point is $\\sqrt{20gl}$. Only tension and gravity act. The minimum tension in the string during the motion is:", "options": ["zero", "mg", "15mg", "10mg"], "answer": 2, "hint": "Minimum at the top: $v^2=20gl-4gl$.", "solution": "$T=\\frac{m(16gl)}{l}-mg=15mg$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q57", "kind": "practice"},
  {"id": "prac-sc-58", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A force $\\vec F=xy\\hat i+x^2y\\hat j$ (SI) acts on a particle moved from O(0,0) to C(1,4) along different paths: OAC (along the x-axis to A(1,0), then up to C), OBC (up the y-axis to B(0,4), then right to C) and ODC (along the parabola $y=4x^2$). The work done along OAC is:", "options": ["8 J", "2 J", "19/3 J", "zero"], "answer": 0, "hint": "On OA, y = 0 so F = 0.", "solution": "A→C (x = 1): $\\int_0^4 y\\,dy=8$ J.", "source": "Sri Chaitanya · Total Physics Important Questions · Q58", "kind": "practice"},
  {"id": "prac-sc-59", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 2, "q": "A force $\\vec F=xy\\hat i+x^2y\\hat j$ (SI) acts on a particle moved from O(0,0) to C(1,4) along different paths: OAC (along the x-axis to A(1,0), then up to C), OBC (up the y-axis to B(0,4), then right to C) and ODC (along the parabola $y=4x^2$). The work done along OBC is:", "options": ["8 J", "2 J", "19/3 J", "zero"], "answer": 1, "hint": "On OB, x = 0 so F = 0.", "solution": "B→C (y = 4): $\\int_0^1 4x\\,dx=2$ J.", "source": "Sri Chaitanya · Total Physics Important Questions · Q59", "kind": "practice"},
  {"id": "prac-sc-60", "exam": "JEE", "subject": "Physics", "chapter": "Work, Energy & Power", "type": "mcq", "difficulty": 3, "q": "A force $\\vec F=xy\\hat i+x^2y\\hat j$ (SI) acts on a particle moved from O(0,0) to C(1,4) along different paths: OAC (along the x-axis to A(1,0), then up to C), OBC (up the y-axis to B(0,4), then right to C) and ODC (along the parabola $y=4x^2$). The work done along ODC is:", "options": ["8 J", "2 J", "19/3 J", "zero"], "answer": 2, "hint": "Use $y=4x^2$, $dy=8x\\,dx$.", "solution": "$\\int_0^1(4x^3+32x^5)dx=1+\\frac{16}{3}=\\frac{19}{3}$ J.", "source": "Sri Chaitanya · Total Physics Important Questions · Q60", "kind": "practice"},
  {"id": "prac-sc-61", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 2, "q": "A disc of mass M and radius R rolls without slipping from rest down a rough incline of angle θ, from A to B, a distance ℓ. f is the friction force and V the speed at B. The speed of the disc at B is:", "options": ["$\\sqrt{2g\\ell\\sin\\theta}$", "$\\sqrt{\\frac{2g\\ell}{3}\\sin\\theta}$", "$\\sqrt{2g\\ell}$", "$\\sqrt{\\frac{4g\\ell}{3}\\sin\\theta}$"], "answer": 3, "hint": "KE of a rolling disc = $\\frac34MV^2$.", "solution": "$\\frac34MV^2=Mg\\ell\\sin\\theta$ ⇒ $V^2=\\frac43g\\ell\\sin\\theta$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q61", "kind": "practice"},
  {"id": "prac-sc-62", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 1, "q": "A disc of mass M and radius R rolls without slipping from rest down a rough incline of angle θ, from A to B, a distance ℓ. f is the friction force and V the speed at B. The kinetic energy of the disc at B is:", "options": ["$Mg\\ell/2$", "$\\frac{3M}{4}V^2$", "$Mg\\ell\\sin\\theta$", "$\\frac23Mg\\ell\\sin\\theta$"], "answer": 1, "hint": "Translational + rotational ($I=\\frac12MR^2$).", "solution": "$\\frac12MV^2+\\frac14MV^2=\\frac34MV^2$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q62", "kind": "practice"},
  {"id": "prac-sc-63", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 3, "q": "A disc of mass M and radius R rolls without slipping from rest down a rough incline of angle θ, from A to B, a distance ℓ. f is the friction force and V the speed at B. The work done by friction $W_f$ is:", "options": ["zero", "$-Mg\\ell\\sin\\theta$", "$\\frac34MV^2-Mg\\ell\\sin\\theta$", "both (A) and (C) are correct"], "answer": 3, "hint": "Rolling without slipping: the contact point doesn't slide.", "solution": "Static friction does no work, and by the work–energy theorem $\\frac34MV^2-Mg\\ell\\sin\\theta=0$ too.", "source": "Sri Chaitanya · Total Physics Important Questions · Q63", "kind": "practice"},
  {"id": "prac-sc-64", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 1, "q": "A 1 kg ball hangs by a 1.50 m thread from the ceiling of a 4 kg trolley that can move freely on horizontal rails. A 1 kg shell moving horizontally at 6 m/s hits the ball and sticks to it (g = 10 m/s²). The velocity of the combined 2 kg mass just after the collision is:", "options": ["3 m/s", "6 m/s", "1 m/s", "1.5 m/s"], "answer": 0, "hint": "Momentum conserved in the brief collision (trolley not involved).", "solution": "$1\\times6=2v$ ⇒ 3 m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q64", "kind": "practice"},
  {"id": "prac-sc-65", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 2, "q": "A 1 kg ball hangs by a 1.50 m thread from the ceiling of a 4 kg trolley that can move freely on horizontal rails. A 1 kg shell moving horizontally at 6 m/s hits the ball and sticks to it (g = 10 m/s²). The trolley's velocity at maximum deflection of the ball is:", "options": ["3 m/s", "6 m/s", "1 m/s", "1.5 m/s"], "answer": 2, "hint": "At maximum deflection ball and trolley share one velocity.", "solution": "$6=6v$ ⇒ 1 m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q65", "kind": "practice"},
  {"id": "prac-sc-66", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 4, "q": "A 1 kg ball hangs by a 1.50 m thread from the ceiling of a 4 kg trolley that can move freely on horizontal rails. A 1 kg shell moving horizontally at 6 m/s hits the ball and sticks to it (g = 10 m/s²). The maximum inclination of the thread with the vertical is:", "options": ["30°", "37°", "45°", "53°"], "answer": 1, "hint": "KE lost = $2mgh$.", "solution": "$9-3=6$ J $=20h$ ⇒ h = 0.3 m ⇒ $\\cos\\phi=\\frac{1.2}{1.5}=0.8$ ⇒ 37°.", "source": "Sri Chaitanya · Total Physics Important Questions · Q66", "kind": "practice"},
  {"id": "prac-sc-67", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "A smooth 8 kg wedge (height 6 m, incline angle 37° at its base) rests on a smooth floor. A 2 kg block is released at the top of the incline. The displacement of the wedge when the block reaches the bottom is:", "options": ["1.6 m", "2 m", "1.5 m", "1.2 m"], "answer": 0, "hint": "Horizontal COM stays fixed; the incline's base is $6/\\tan37°=8$ m.", "solution": "$2(8-x)=8x$ ⇒ x = 1.6 m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q67", "kind": "practice"},
  {"id": "prac-sc-68", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "A smooth 8 kg wedge (height 6 m, incline angle 37° at its base) rests on a smooth floor. A 2 kg block is released at the top of the incline. Seen from the ground, the block moves:", "options": ["at 37° below the horizontal", "at more than 37° below the horizontal", "at 90° to the horizontal", "horizontally"], "answer": 1, "hint": "The wedge recoils, reducing the block's horizontal velocity.", "solution": "Its vertical velocity is unchanged while its horizontal one shrinks ⇒ steeper than 37°.", "source": "Sri Chaitanya · Total Physics Important Questions · Q68", "kind": "practice"},
  {"id": "prac-sc-70", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 2, "q": "A 100 kg uniform plank of length 20 m lies on a smooth horizontal floor. A 25 kg boy walks from end A to end B at 0.5 m/s relative to the plank. The boy's displacement relative to the ground when he reaches B is:", "options": ["20 m", "16 m", "15 m", "12 m"], "answer": 1, "hint": "No external horizontal force: $25x_b=100x_p$, $x_b+x_p=20$.", "solution": "$x_p=4$ m ⇒ boy moves 16 m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q70", "kind": "practice"},
  {"id": "prac-sc-71", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 2, "q": "A 100 kg uniform plank of length 20 m lies on a smooth horizontal floor. A 25 kg boy walks from end A to end B at 0.5 m/s relative to the plank. The velocity of the plank is:", "options": ["10 cm/s", "12.5 cm/s", "25 cm/s", "50 cm/s"], "answer": 0, "hint": "$25v_b=100v_p$ and $v_b+v_p=0.5$.", "solution": "$v_p=0.1$ m/s = 10 cm/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q71", "kind": "practice"},
  {"id": "prac-sc-72", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 2, "q": "A 100 kg uniform plank of length 20 m lies on a smooth horizontal floor. A 25 kg boy walks from end A to end B at 0.5 m/s relative to the plank. Choose the INCORRECT statement:", "options": ["Momentum of the whole system is conserved", "Momentum of the boy can't stay conserved because of friction", "Momentum of the plank can't stay conserved because of friction", "The centre of mass of the whole system moves along +x"], "answer": 3, "hint": "No external horizontal force acts on boy + plank.", "solution": "The system's COM stays at rest, so (D) is incorrect.", "source": "Sri Chaitanya · Total Physics Important Questions · Q72", "kind": "practice"},
  {"id": "prac-sc-73", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 3, "q": "A ring of mass M and radius R sliding (not rotating) with velocity $v_0$ enters a rough surface with friction coefficient μ. Choose the INCORRECT statement:", "options": ["Friction does negative translational work", "Friction does positive rotational work", "The net work done by friction is zero", "Friction converts translational KE into rotational KE"], "answer": 2, "hint": "Kinetic friction acts while the ring slips.", "solution": "Energy is dissipated during slipping, so the net work by friction is negative, not zero.", "source": "Sri Chaitanya · Total Physics Important Questions · Q73", "kind": "practice"},
  {"id": "prac-sc-74", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 3, "q": "A ring of mass M and radius R sliding (not rotating) with velocity $v_0$ enters a rough surface with friction coefficient μ. The velocity of the centre of the ring when it starts pure rolling is:", "options": ["$v_0/4$", "$v_0/2$", "$v_0/3$", "$2v_0/3$"], "answer": 1, "hint": "Angular momentum about the contact point is conserved.", "solution": "$Mv_0R=Mv R+MR^2\\frac vR$ ⇒ $v=\\frac{v_0}{2}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q74", "kind": "practice"},
  {"id": "prac-sc-75", "exam": "JEE", "subject": "Physics", "chapter": "Rotational Motion", "type": "mcq", "difficulty": 3, "q": "A ring of mass M and radius R sliding (not rotating) with velocity $v_0$ enters a rough surface with friction coefficient μ. The distance moved by its centre on the rough surface before pure rolling starts is:", "options": ["$\\frac{3v_0^2}{8\\mu g}$", "$\\frac{2v_0^2}{8\\mu g}$", "$\\frac{v_0^2}{\\mu g}$", "$\\frac{5v_0^2}{8\\mu g}$"], "answer": 0, "hint": "Rolling starts at $v=v_0/2$ with deceleration μg.", "solution": "$t=\\frac{v_0}{2\\mu g}$, $s=\\frac{v_0^2-v_0^2/4}{2\\mu g}=\\frac{3v_0^2}{8\\mu g}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q75", "kind": "practice"},
  {"id": "prac-sc-76", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "Blocks $m_1$ and $m_2$ joined by an ideal spring (constant K) rest on a smooth table. A constant horizontal force F pulls $m_1$ away from $m_2$. The maximum elongation of the spring during the motion is $x_0$. Both blocks have the same velocity when the elongation is:", "options": ["$\\frac{m_2F}{2K(m_1+m_2)}$", "$\\frac{m_2F}{K(m_1+m_2)}$", "$\\frac{2m_2F}{K(m_1+m_2)}$", "$\\frac{4m_2F}{K(m_1+m_2)}$"], "answer": 2, "hint": "Equal velocities ⇔ relative velocity zero ⇔ maximum elongation.", "solution": "In the COM frame the reduced system oscillates about $\\frac{m_2F}{K(m_1+m_2)}$, so the maximum is twice that.", "source": "Sri Chaitanya · Total Physics Important Questions · Q76", "kind": "practice"},
  {"id": "prac-sc-77", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "Blocks $m_1$ and $m_2$ joined by an ideal spring (constant K) rest on a smooth table. A constant horizontal force F pulls $m_1$ away from $m_2$. The maximum elongation of the spring during the motion is $x_0$. Both blocks have the same acceleration when the elongation is:", "options": ["$\\frac{m_2F}{2K(m_1+m_2)}$", "$\\frac{m_2F}{K(m_1+m_2)}$", "$\\frac{2m_2F}{K(m_1+m_2)}$", "$\\frac{4m_2F}{K(m_1+m_2)}$"], "answer": 1, "hint": "Both then accelerate at $\\frac{F}{m_1+m_2}$.", "solution": "For $m_2$: $Kx=m_2\\frac{F}{m_1+m_2}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q77", "kind": "practice"},
  {"id": "prac-sc-78", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "Blocks $m_1$ and $m_2$ joined by an ideal spring (constant K) rest on a smooth table. A constant horizontal force F pulls $m_1$ away from $m_2$. The maximum elongation of the spring during the motion is $x_0$. Select the correct alternative:", "options": ["The velocity of the COM equals that of $m_1$ and $m_2$ when the elongation is $x_0$", "It equals theirs when the elongation is $x_0/2$", "It can never equal theirs", "The COM velocity can become zero during the motion"], "answer": 0, "hint": "When do both blocks share one velocity?", "solution": "At maximum elongation both move together, so they also move with the COM.", "source": "Sri Chaitanya · Total Physics Important Questions · Q78", "kind": "practice"},
  {"id": "prac-sc-79", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "A dumbbell is a massless rod of length l with a particle of mass M at each end, at rest in free space. An impulse Δp is given to one sphere: in case (a) perpendicular to the rod, in case (b) along the rod. In case (a), the COM velocity and angular velocity are:", "options": ["$\\frac{\\Delta p}{M}$; $\\frac{\\Delta p}{2Ml}$", "$\\frac{\\Delta p}{2M}$; $\\frac{\\Delta p}{Ml}$", "$\\frac{2\\Delta p}{M}$; $\\frac{\\Delta p}{4Ml}$", "$\\frac{\\Delta p}{2M}$; $\\frac{\\Delta p}{2Ml}$"], "answer": 1, "hint": "Angular impulse about the COM = $\\Delta p\\cdot\\frac l2$; $I=\\frac{Ml^2}{2}$.", "solution": "$v=\\frac{\\Delta p}{2M}$, $\\omega=\\frac{\\Delta p\\,l/2}{Ml^2/2}=\\frac{\\Delta p}{Ml}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q79", "kind": "practice"},
  {"id": "prac-sc-80", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 2, "q": "A dumbbell is a massless rod of length l with a particle of mass M at each end, at rest in free space. An impulse Δp is given to one sphere: in case (a) perpendicular to the rod, in case (b) along the rod. In case (b), the COM velocity and angular velocity are:", "options": ["$\\frac{\\Delta p}{M}$; $\\frac{\\Delta p}{2Ml}$", "$\\frac{\\Delta p}{2M}$; $\\frac{\\Delta p}{Ml}$", "$\\frac{\\Delta p}{2M}$; 0", "$\\frac{\\Delta p}{M}$; 0"], "answer": 2, "hint": "An impulse along the rod has no moment about the COM.", "solution": "$v=\\frac{\\Delta p}{2M}$, ω = 0.", "source": "Sri Chaitanya · Total Physics Important Questions · Q80", "kind": "practice"},
  {"id": "prac-sc-81", "exam": "JEE", "subject": "Physics", "chapter": "Centre of Mass & Collisions", "type": "mcq", "difficulty": 3, "q": "A dumbbell is a massless rod of length l with a particle of mass M at each end, at rest in free space. An impulse Δp is given to one sphere: in case (a) perpendicular to the rod, in case (b) along the rod. The energies given to the dumbbell in cases (a) and (b) are:", "options": ["$\\frac{(\\Delta p)^2}{2M}$; $\\frac{(\\Delta p)^2}{4M}$", "$\\frac{(\\Delta p)^2}{4M}$; $\\frac{(\\Delta p)^2}{2M}$", "$\\frac{(\\Delta p)^2}{2M}$; $\\frac{(\\Delta p)^2}{2M}$", "$\\frac{(\\Delta p)^2}{4M}$; $\\frac{(\\Delta p)^2}{4M}$"], "answer": 0, "hint": "Add translational and rotational KE.", "solution": "(a) $\\frac{\\Delta p^2}{4M}+\\frac12\\cdot\\frac{Ml^2}{2}\\cdot\\frac{\\Delta p^2}{M^2l^2}=\\frac{\\Delta p^2}{2M}$; (b) $\\frac{\\Delta p^2}{4M}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q81", "kind": "practice"},
  {"id": "prac-sc-82", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 3, "q": "A geosynchronous satellite of mass m moves in a circular orbit of radius $r_0$ with speed $v_0$. By mistake its engine fires briefly towards the Earth, giving a radial velocity change Δv (inward-directed thrust, so the boost is radial). Let $\\beta=\\Delta v/v_0<1$. The new trajectory is:", "options": ["parabolic", "elliptic", "hyperbolic", "circular"], "answer": 1, "hint": "Compare the new energy with zero.", "solution": "$E=-\\frac12mv_0^2(1-\\beta^2)<0$ and the orbit is no longer circular ⇒ ellipse.", "source": "Sri Chaitanya · Total Physics Important Questions · Q82", "kind": "practice"},
  {"id": "prac-sc-83", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 5, "q": "A geosynchronous satellite of mass m moves in a circular orbit of radius $r_0$ with speed $v_0$. By mistake its engine fires briefly towards the Earth, giving a radial velocity change Δv (inward-directed thrust, so the boost is radial). Let $\\beta=\\Delta v/v_0<1$. The minimum distance of the satellite from the Earth's centre is:", "options": ["$\\frac{\\beta r_0}{2}$", "$\\frac{r_0}{1+\\beta^2}$", "$\\frac{r_0}{1+\\beta}$", "$\\frac{r_0}{1+\\sqrt{2\\beta}}$"], "answer": 2, "hint": "A radial kick keeps L, so the semi-latus rectum stays $r_0$.", "solution": "Eccentricity $\\varepsilon=\\beta$, so $r_{min}=\\frac{l}{1+\\varepsilon}=\\frac{r_0}{1+\\beta}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q83", "kind": "practice"},
  {"id": "prac-sc-84", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 5, "q": "A geosynchronous satellite of mass m moves in a circular orbit of radius $r_0$ with speed $v_0$. By mistake its engine fires briefly towards the Earth, giving a radial velocity change Δv (inward-directed thrust, so the boost is radial). Let $\\beta=\\Delta v/v_0<1$. For β = 1/4, the new period is about (the original period is 24 h):", "options": ["20 h", "26 h", "67.9 h", "48 h"], "answer": 1, "hint": "Semi-major axis $=\\frac{r_0}{1-\\beta^2}$; Kepler's third law.", "solution": "$a=\\frac{16}{15}r_0$ ⇒ $T=24\\left(\\frac{16}{15}\\right)^{3/2}\\approx26$ h.", "source": "Sri Chaitanya · Total Physics Important Questions · Q84", "kind": "practice"},
  {"id": "prac-sc-85", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 2, "q": "A particle of mass m is on the axis of a thin ring (mass M, radius a), at a distance x from its centre. The gravitational potential energy of the system is:", "options": ["$-\\frac{GMm}{\\sqrt{a^2+x^2}}$", "$\\frac{GMm}{a}$", "$\\frac{GMm}{x}$", "None of these"], "answer": 0, "hint": "Every element of the ring is at the same distance.", "solution": "$U=-\\frac{GMm}{\\sqrt{a^2+x^2}}$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q85", "kind": "practice"},
  {"id": "prac-sc-86", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 1, "q": "A particle of mass m is on the axis of a thin ring (mass M, radius a), at a distance x from its centre. The force on m when x = 0 is:", "options": ["$\\frac{GMm}{x^2}$", "$\\frac{GMm\\,x}{\\sqrt{a^2+x^2}}$", "$\\frac{GMm\\,x}{(a^2+x^2)^{3/2}}$", "zero"], "answer": 3, "hint": "Symmetry at the centre.", "solution": "All pulls cancel at the centre ⇒ zero.", "source": "Sri Chaitanya · Total Physics Important Questions · Q86", "kind": "practice"},
  {"id": "prac-sc-88", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 3, "q": "A satellite moves round the Earth in a circular orbit of radius a with speed $v_0$. A particle is projected from it in the forward direction with velocity $\\left(\\sqrt{5/4}-1\\right)v_0$ relative to the satellite. The path traced by the projected particle is:", "options": ["circle", "ellipse", "straight line", "none of these"], "answer": 1, "hint": "Its speed is $\\sqrt{5/4}\\,v_0$: between orbital and escape speed.", "solution": "$v_0<v<\\sqrt2v_0$ ⇒ ellipse.", "source": "Sri Chaitanya · Total Physics Important Questions · Q88", "kind": "practice"},
  {"id": "prac-sc-89", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 3, "q": "A satellite moves round the Earth in a circular orbit of radius a with speed $v_0$. A particle is projected from it in the forward direction with velocity $\\left(\\sqrt{5/4}-1\\right)v_0$ relative to the satellite. The particle's minimum distance from the Earth's centre is:", "options": ["a", "a/2", "3a", "5a/4"], "answer": 0, "hint": "It is launched tangentially, so the launch point is an apsis.", "solution": "Faster than circular speed ⇒ launch point is the perigee: a.", "source": "Sri Chaitanya · Total Physics Important Questions · Q89", "kind": "practice"},
  {"id": "prac-sc-90", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 4, "q": "A satellite moves round the Earth in a circular orbit of radius a with speed $v_0$. A particle is projected from it in the forward direction with velocity $\\left(\\sqrt{5/4}-1\\right)v_0$ relative to the satellite. The particle's maximum distance from the Earth's centre is:", "options": ["a", "5a/4", "infinity", "5a/3"], "answer": 3, "hint": "Use energy and angular momentum conservation between the apsides.", "solution": "With r = ka: $3k^2-8k+5=0$ ⇒ k = 5/3.", "source": "Sri Chaitanya · Total Physics Important Questions · Q90", "kind": "practice"},
  {"id": "prac-sc-91", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 2, "q": "A person brings a 1 kg mass from infinity (at rest) to point A, where it moves at 2 m/s. The work done by the person is −3 J. The gravitational potential at A is:", "options": ["−3 J/kg", "−2 J/kg", "−5 J/kg", "−7 J/kg"], "answer": 2, "hint": "$W_{person}+W_{gravity}=\\Delta K$.", "solution": "$W_g=2+3=5$ J ⇒ $U_A=-5$ J ⇒ V = −5 J/kg.", "source": "Sri Chaitanya · Total Physics Important Questions · Q91", "kind": "practice"},
  {"id": "prac-sc-92", "exam": "JEE", "subject": "Physics", "chapter": "Gravitation", "type": "mcq", "difficulty": 1, "q": "The gravitational potential inside a hollow sphere (mass M, radius R) at distance r from its centre is:", "options": ["zero", "$-\\frac{GM}{R}$", "$-\\frac{GM}{r}$", "$-\\frac{GM}{r^2}$"], "answer": 1, "hint": "The field inside is zero.", "solution": "Constant potential equal to its surface value: $-GM/R$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q92", "kind": "practice"},
  {"id": "prac-sc-100", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 4, "q": "Poiseuille's equation gives the volume flow rate through a narrow tube as $Q=\\frac{\\pi P r^4}{8\\eta\\ell}$. Take the viscosity of blood as $4\\times10^{-3}$ N s/m². A major artery of radius 0.4 cm carries blood at 5 cm³/s. The pressure difference per metre of artery is about (density of mercury 13.6 g/cm³):", "options": ["9.6 mm of Hg", "3.2 mm of Hg", "1.5 mm of Hg", "8.6 mm of Hg"], "answer": 2, "hint": "$\\frac{P}{\\ell}=\\frac{8\\eta Q}{\\pi r^4}$.", "solution": "$\\frac{8\\times4\\times10^{-3}\\times5\\times10^{-6}}{\\pi(4\\times10^{-3})^4}\\approx199$ Pa/m ≈ 1.5 mm Hg.", "source": "Sri Chaitanya · Total Physics Important Questions · Q100", "kind": "practice"},
  {"id": "prac-sc-101", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "Poiseuille's equation gives the volume flow rate through a narrow tube as $Q=\\frac{\\pi P r^4}{8\\eta\\ell}$. Take the viscosity of blood as $4\\times10^{-3}$ N s/m². If the average arterial pressure is about 100 mm of Hg, the 1.5 mm Hg per metre drop found for a major artery suggests:", "options": ["viscous effects are significant, so Bernoulli's equation doesn't apply", "viscous effects are insignificant in major arteries, so Bernoulli's equation applies", "it's impossible to judge", "Bernoulli's equation doesn't depend on viscosity"], "answer": 1, "hint": "Compare 1.5 with 100.", "solution": "The viscous drop is tiny compared with the pressure, so viscosity can be neglected.", "source": "Sri Chaitanya · Total Physics Important Questions · Q101", "kind": "practice"},
  {"id": "prac-sc-102", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "The average blood pressure at the heart is 100 mm of Hg. Taking blood density $10^3$ kg/m³ and g = 10 m/s², the average pressure in the leg of a standing person 1 m below the heart is nearly:", "options": ["92 mm of Hg", "100 mm of Hg", "144 mm of Hg", "174 mm of Hg"], "answer": 3, "hint": "Add ρgh and convert to mm Hg.", "solution": "$\\rho gh=10^4$ Pa ≈ 74 mm Hg ⇒ 174 mm Hg.", "source": "Sri Chaitanya · Total Physics Important Questions · Q102", "kind": "practice"},
  {"id": "prac-sc-106", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 3, "q": "A cylindrical tank of cross-section 0.5 m² holds two immiscible liquids, each 60 cm deep: $\\rho_1=900$ kg/m³ at the bottom and $\\rho_2=600$ kg/m³ on top. A small hole of area 5 cm² is made in the right wall 20 cm above the bottom (g = 10 m/s²). The speed of efflux is:", "options": ["4 m/s", "5 m/s", "6 m/s", "2 m/s"], "answer": 0, "hint": "Gauge pressure at the hole: $\\rho_2gh+\\rho_1g(h-y)$.", "solution": "$3600+3600=7200$ Pa $=\\frac12\\rho_1v^2$ ⇒ v = 4 m/s.", "source": "Sri Chaitanya · Total Physics Important Questions · Q106", "kind": "practice"},
  {"id": "prac-sc-107", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 3, "q": "A cylindrical tank of cross-section 0.5 m² holds two immiscible liquids, each 60 cm deep: $\\rho_1=900$ kg/m³ at the bottom and $\\rho_2=600$ kg/m³ on top. A small hole of area 5 cm² is made in the right wall 20 cm above the bottom (g = 10 m/s²). If the tank rests on a smooth floor, the horizontal force F needed to keep it in equilibrium is:", "options": ["5.2 N", "7.2 N", "6.2 N", "8.2 N"], "answer": 1, "hint": "Thrust of the jet = $\\rho av^2$.", "solution": "$900\\times5\\times10^{-4}\\times16=7.2$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q107", "kind": "practice"},
  {"id": "prac-sc-108", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 4, "q": "A cylindrical tank of cross-section 0.5 m² holds two immiscible liquids, each 60 cm deep: $\\rho_1=900$ kg/m³ at the bottom and $\\rho_2=600$ kg/m³ on top. A small hole of area 5 cm² is made in the right wall 20 cm above the bottom (g = 10 m/s²). If the friction coefficient with the floor is 0.01, the maximum F (applied on the side opposite the hole) that keeps the tank at rest is:", "options": ["62.2 N", "32.2 N", "52.2 N", "42.2 N"], "answer": 2, "hint": "Weight of liquids = $(900+600)\\times0.5\\times0.6\\times10$.", "solution": "Weight 4500 N ⇒ friction up to 45 N ⇒ $F_{max}=7.2+45=52.2$ N.", "source": "Sri Chaitanya · Total Physics Important Questions · Q108", "kind": "practice"},
  {"id": "prac-sc-109", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 3, "q": "A 2 kg ball is released from the bottom of a tank of water (ideal liquid) 2 m deep. On reaching the surface its kinetic energy is 16 J. Only gravity and upthrust act (g = 10 m/s²). Choose the INCORRECT option:", "options": ["Work done by gravity is −40 J", "Work done by upthrust is 56 J", "The work–energy theorem can be applied", "A free-falling observer finds the work done by gravity on the ball is zero"], "answer": 3, "hint": "Work depends on displacement in that frame.", "solution": "(A),(B),(C) are true (56 − 40 = 16). In the free-falling frame the ball still moves relative to the observer, so gravity's work is not zero.", "source": "Sri Chaitanya · Total Physics Important Questions · Q109", "kind": "practice"},
  {"id": "prac-sc-111", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "A 2 kg ball is released from the bottom of a tank of water (ideal liquid) 2 m deep. On reaching the surface its kinetic energy is 16 J. Only gravity and upthrust act (g = 10 m/s²). Select the correct option:", "options": ["In gravity-free space the upthrust is non-zero", "From bottom to top the ball's acceleration is variable", "The ball's material is less dense than water", "Upthrust does not depend on g"], "answer": 2, "hint": "Upthrust (28 N) vs weight (20 N).", "solution": "$W_{up}=56$ J over 2 m ⇒ 28 N > 20 N ⇒ ball is less dense than water. Upthrust ∝ g, and acceleration is constant.", "source": "Sri Chaitanya · Total Physics Important Questions · Q111", "kind": "practice"},
  {"id": "prac-sc-112", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 1, "q": "Four open containers of different shapes hold the same oil. Rank them by the pressure at depth h, greatest first:", "options": ["A, C, B", "B, A, C", "C, A, B", "All tie"], "answer": 3, "hint": "Hydrostatic pressure depends only on depth.", "solution": "$P=P_0+\\rho gh$ for all ⇒ all tie.", "source": "Sri Chaitanya · Total Physics Important Questions · Q112", "kind": "practice"},
  {"id": "prac-sc-113", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 1, "q": "A penguin floats in fluids of densities $\\rho_0$, $0.95\\rho_0$ and $1.1\\rho_0$. Rank the fluids by buoyant force on it, greatest first:", "options": ["1.1ρ₀, ρ₀, 0.95ρ₀", "0.95ρ₀, ρ₀, 1.1ρ₀", "ρ₀, 0.95ρ₀, 1.1ρ₀", "All tie"], "answer": 3, "hint": "It floats in each.", "solution": "Floating ⇒ buoyant force = weight in every case.", "source": "Sri Chaitanya · Total Physics Important Questions · Q113", "kind": "practice"},
  {"id": "prac-sc-114", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "A penguin floats in fluids of densities $\\rho_0$, $0.95\\rho_0$ and $1.1\\rho_0$. Rank the fluids by the volume displaced, greatest first:", "options": ["1.1ρ₀, ρ₀, 0.95ρ₀", "0.95ρ₀, ρ₀, 1.1ρ₀", "ρ₀, 0.95ρ₀, 1.1ρ₀", "All tie"], "answer": 1, "hint": "Same buoyant force, $V=\\frac{W}{\\rho g}$.", "solution": "Least dense fluid needs the most volume.", "source": "Sri Chaitanya · Total Physics Important Questions · Q114", "kind": "practice"},
  {"id": "prac-sc-115", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "A siphon of uniform cross-section works as shown. A is inside the siphon at the water level of the container, D is at the same level as A, E is the open end. AB = CD = $h_1$ and DE = $h_2$. Once flow is established:", "img": "figures/prac-sc-p39.png", "imgAlt": "Siphon: short arm from A (at the water level) up to B, across to C, down past D (level with A) to the open end E", "options": ["$P_B>P_C$", "$P_B=P_C$", "$P_B<P_C$", "$P_B$ and $P_C$ can't be predicted"], "answer": 1, "hint": "Same height, same speed (uniform tube).", "solution": "Bernoulli ⇒ equal pressures.", "source": "Sri Chaitanya · Total Physics Important Questions · Q115", "kind": "practice"},
  {"id": "prac-sc-116", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "A siphon of uniform cross-section works as shown. A is inside the siphon at the water level of the container, D is at the same level as A, E is the open end. AB = CD = $h_1$ and DE = $h_2$. The flow speed depends on:", "img": "figures/prac-sc-p39.png", "imgAlt": "Siphon: short arm from A (at the water level) up to B, across to C, down past D (level with A) to the open end E", "options": ["$h_1$ only", "$h_2$ only", "both $h_1$ and $h_2$", "neither"], "answer": 1, "hint": "Apply Bernoulli from the free surface to E.", "solution": "$v=\\sqrt{2gh_2}$ since E is $h_2$ below the water level.", "source": "Sri Chaitanya · Total Physics Important Questions · Q116", "kind": "practice"},
  {"id": "prac-sc-117", "exam": "JEE", "subject": "Physics", "chapter": "Mechanical Properties of Fluids", "type": "mcq", "difficulty": 2, "q": "A siphon of uniform cross-section works as shown. A is inside the siphon at the water level of the container, D is at the same level as A, E is the open end. AB = CD = $h_1$ and DE = $h_2$. The pressure at A is:", "img": "figures/prac-sc-p39.png", "imgAlt": "Siphon: short arm from A (at the water level) up to B, across to C, down past D (level with A) to the open end E", "options": ["greater than atmospheric", "equal to atmospheric", "less than atmospheric", "can't be predicted"], "answer": 2, "hint": "A is at surface level but the water there is moving.", "solution": "$P_A=P_0-\\frac12\\rho v^2<P_0$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q117", "kind": "practice"},
  {"id": "prac-sc-118", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A pipe closed at one end, 0.90 m long, resonates with a tone of wavelength 0.72 m. Which harmonic is this?", "options": ["2", "4", "6", "5"], "answer": 3, "hint": "Closed pipe: $L=\\frac{n\\lambda}{4}$, n odd.", "solution": "$n=\\frac{4\\times0.9}{0.72}=5$.", "source": "Sri Chaitanya · Total Physics Important Questions · Q118", "kind": "practice"},
  {"id": "prac-sc-119", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 1, "q": "A pipe closed at one end, 0.90 m long, resonates with a tone of wavelength 0.72 m. The distance between a node and the adjacent antinode (m) is closest to:", "options": ["0.18", "0.36", "0.27", "0.22"], "answer": 0, "hint": "It's λ/4.", "solution": "$0.72/4=0.18$ m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q119", "kind": "practice"},
  {"id": "prac-sc-120", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A pipe closed at one end, 0.90 m long, resonates with a tone of wavelength 0.72 m. The wavelength of the next higher overtone (m) is closest to:", "options": ["0.40", "0.58", "0.36", "0.51"], "answer": 3, "hint": "Next allowed harmonic is the 7th.", "solution": "$\\lambda=\\frac{4\\times0.9}{7}=0.51$ m.", "source": "Sri Chaitanya · Total Physics Important Questions · Q120", "kind": "practice"},
  {"id": "prac-sc-121", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A wave pulse on a string travels in the −x direction as shown. Kinetic energy is maximum for particle:", "img": "figures/prac-sc-p41.png", "imgAlt": "A pulse with crest near C and trough near G; points A–I marked along it, moving in −x", "options": ["D", "E", "F", "G"], "answer": 1, "hint": "Speed is greatest where the slope is steepest.", "solution": "E is at the mean position of the steep part.", "source": "Sri Chaitanya · Total Physics Important Questions · Q121", "kind": "practice"},
  {"id": "prac-sc-122", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 2, "q": "A wave pulse on a string travels in the −x direction as shown. Potential energy is maximum for particle:", "img": "figures/prac-sc-p41.png", "imgAlt": "A pulse with crest near C and trough near G; points A–I marked along it, moving in −x", "options": ["D", "E", "F", "G"], "answer": 1, "hint": "PE density ∝ (slope)².", "solution": "The string is most stretched at E.", "source": "Sri Chaitanya · Total Physics Important Questions · Q122", "kind": "practice"},
  {"id": "prac-sc-123", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 3, "q": "A wave pulse on a string travels in the −x direction as shown. Particles B and D are moving respectively:", "img": "figures/prac-sc-p41.png", "imgAlt": "A pulse with crest near C and trough near G; points A–I marked along it, moving in −x", "options": ["up, up", "down, down", "up, down", "down, up"], "answer": 2, "hint": "For a wave moving in −x, $v_y=+v\\frac{\\partial y}{\\partial x}$.", "solution": "B is on a rising slope ⇒ up; D on a falling slope ⇒ down.", "source": "Sri Chaitanya · Total Physics Important Questions · Q123", "kind": "practice"},
  {"id": "prac-sc-124", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 4, "q": "A string 150 cm long, fixed at both ends, vibrates in a standing wave. The amplitude at 10 cm from one end is $5\\sqrt3$ mm, and the two nearest points in the same loop with amplitude $5\\sqrt3$ mm are 10 cm apart. The maximum displacement amplitude in the string is:", "options": ["10 mm", "$20/\\sqrt3$ mm", "$10\\sqrt3$ mm", "20 mm"], "answer": 0, "hint": "The two points sit symmetrically in a loop: $\\frac\\lambda2-20=10$.", "solution": "λ = 60 cm; $A\\sin\\frac{2\\pi(10)}{60}=5\\sqrt3$ ⇒ A = 10 mm.", "source": "Sri Chaitanya · Total Physics Important Questions · Q124", "kind": "practice"},
  {"id": "prac-sc-125", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 3, "q": "A string 150 cm long, fixed at both ends, vibrates in a standing wave. The amplitude at 10 cm from one end is $5\\sqrt3$ mm, and the two nearest points in the same loop with amplitude $5\\sqrt3$ mm are 10 cm apart. The overtone produced is the:", "options": ["2nd", "3rd", "4th", "6th"], "answer": 2, "hint": "Count loops: $150/30$.", "solution": "5 loops ⇒ 5th harmonic ⇒ 4th overtone.", "source": "Sri Chaitanya · Total Physics Important Questions · Q125", "kind": "practice"},
  {"id": "prac-sc-126", "exam": "JEE", "subject": "Physics", "chapter": "Waves", "type": "mcq", "difficulty": 3, "q": "A string 150 cm long, fixed at both ends, vibrates in a standing wave. The amplitude at 10 cm from one end is $5\\sqrt3$ mm, and the two nearest points in the same loop with amplitude $5\\sqrt3$ mm are 10 cm apart. At what minimum distance from one end is the string's potential energy zero (the end having maximum PE)?", "options": ["$10\\sqrt3$ cm", "15 cm", "20 cm", "30 cm"], "answer": 1, "hint": "PE is zero where the strain is zero: an antinode.", "solution": "Nearest antinode is λ/4 = 15 cm from the end.", "source": "Sri Chaitanya · Total Physics Important Questions · Q126", "kind": "practice"}
);
